shell_commands:
/bin/zsh -lc "cat > src/orchestration/beforeSession.error.test.ts <<'EOF'
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

it('passes the session and error to onError when beforeSession fails [specs/hal-engine-config-hooks/spec.md#7]', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const failure = new Error('setup failed');
  let received: unknown[] = [];
  const orchestrator = createChatOrchestrator({} as AIProvider, new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {
      beforeSession: async () => {
        throw failure;
      },
      onError: async (hookSession, error) => {
        received = [hookSession, error];
      },
    },
  });

  await expect(orchestrator.processMessage(session)).rejects.toBe(failure);
  expect(received).toEqual([session, failure]);
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/beforeSession.error.test.ts"
